package com.companages.repository;
import com.companages.entity.Organization; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface OrganizationRepository extends JpaRepository<Organization,Long>{ List<Organization> findAllByOwnerIdOrderByCreatedAtDesc(Long ownerId); Optional<Organization> findByIdAndOwnerId(Long id,Long ownerId); long countByOwnerId(Long ownerId); @Query("select distinct o from Organization o join Member m on m.organization=o where m.user.id=:userId order by o.createdAt desc") List<Organization> findAllForUser(@Param("userId")Long userId); @Query("select o from Organization o join Member m on m.organization=o where o.id=:id and m.user.id=:userId") Optional<Organization> findAccessible(@Param("id")Long id,@Param("userId")Long userId); @Query("select count(distinct o.id) from Organization o join Member m on m.organization=o where m.user.id=:userId") long countForUser(@Param("userId")Long userId); }
